package shell

import (
	"bytes"
	"fmt"
	"text/template"
)

const zshTemplate = `# LNTA Shell Integration for zsh
# Generated by lnta {{.Version}}
# Source with: eval "$(lnta init zsh)"

# PrecMD hook: capture last command and exit code on every prompt
__lnta_precmd() {
    local exit_code=$?
    export _LNTA_LAST_EXIT=$exit_code
    export _LNTA_LAST_CMD="${history[$((HISTCMD-1))]}"
}
autoload -Uz add-zsh-hook
add-zsh-hook precmd __lnta_precmd

# lnta fix function: invoke lnta fix with captured environment
lnta_fix() {
    if [[ -z "${_LNTA_LAST_CMD:-}" ]]; then
        echo "No previous command to fix. Run a command first." >&2
        return 1
    fi
    _LNTA_LAST_CMD="${_LNTA_LAST_CMD}" _LNTA_LAST_EXIT="${_LNTA_LAST_EXIT}" lnta fix
}

# Ctrl+G widget: replace buffer with verified command from lnta --command-only
_lnta_ctrl_g_widget() {
    local original_buffer="$BUFFER"
    local cmd
    cmd=$(lnta --command-only "$BUFFER" 2>/dev/null)
    if [[ $? -eq 0 && -n "$cmd" ]]; then
        BUFFER="$cmd"
        zle reset-prompt
    else
        zle -M "lnta: failed to generate command"
    fi
}
zle -N _lnta_ctrl_g_widget
bindkey '^G' _lnta_ctrl_g_widget

# Ctrl+X, then Ctrl+G: run the existing lnta fix workflow
_lnta_ctrl_x_ctrl_g_fix_widget() {
    BUFFER="lnta_fix"
    zle accept-line
}
zle -N _lnta_ctrl_x_ctrl_g_fix_widget
bindkey '^X^G' _lnta_ctrl_x_ctrl_g_fix_widget
`

const bashTemplate = `# LNTA Shell Integration for bash
# Generated by lnta {{.Version}}
# Source with: eval "$(lnta init bash)"

# PROMPT_COMMAND hook: capture last command and exit code
_lnta_prompt_command() {
    local exit_code=$?
    export _LNTA_LAST_EXIT=$exit_code
    export _LNTA_LAST_CMD="${BASH_COMMAND}"
}
# Append to PROMPT_COMMAND (preserve existing)
if [[ -n "${PROMPT_COMMAND:-}" ]]; then
    PROMPT_COMMAND="${PROMPT_COMMAND}; _lnta_prompt_command"
else
    PROMPT_COMMAND="_lnta_prompt_command"
fi

# lnta fix function: invoke lnta fix with captured environment
lnta_fix() {
    if [[ -z "${_LNTA_LAST_CMD:-}" ]]; then
        echo "No previous command to fix. Run a command first." >&2
        return 1
    fi
    _LNTA_LAST_CMD="${_LNTA_LAST_CMD}" _LNTA_LAST_EXIT="${_LNTA_LAST_EXIT}" lnta fix
}

# Ctrl+G widget: replace buffer with verified command from lnta --command-only
_lnta_ctrl_g_widget() {
    local original_buffer="$READLINE_LINE"
    local cmd
    cmd=$(lnta --command-only "$READLINE_LINE" 2>/dev/null)
    if [[ $? -eq 0 && -n "$cmd" ]]; then
        READLINE_LINE="$cmd"
        READLINE_POINT=${#cmd}
    else
        echo "lnta: failed to generate command" >&2
    fi
}
bind -x '"\C-g": _lnta_ctrl_g_widget'
bind '"\C-x\C-g":"lnta_fix\n"'
`

const fishTemplate = `# LNTA Shell Integration for fish
# Generated by lnta {{.Version}}
# Source with: eval "$(lnta init fish)"

# fish_prompt hook: capture last command and exit code
function _lnta_fish_prompt --on-event fish_prompt
    set -l last_status $status
    set -gx _LNTA_LAST_EXIT $last_status
    set -gx _LNTA_LAST_CMD $history[1]
end

# lnta fix function: invoke lnta fix with captured environment
function lnta_fix
    if not set -q _LNTA_LAST_CMD
        echo "No previous command to fix. Run a command first." >&2
        return 1
    end
    env _LNTA_LAST_CMD="$_LNTA_LAST_CMD" _LNTA_LAST_EXIT="$_LNTA_LAST_EXIT" lnta fix
end

# Ctrl+G widget: replace buffer with verified command from lnta --command-only
function _lnta_ctrl_g_widget
    set -l original_buffer $commandline
    set -l cmd (lnta --command-only "$commandline" 2>/dev/null)
    if test $status -eq 0 -a -n "$cmd"
        commandline -r "$cmd"
    else
        echo "lnta: failed to generate command" >&2
    end
end
bind \cg _lnta_ctrl_g_widget

function _lnta_ctrl_x_ctrl_g_fix
    commandline -r lnta_fix
    commandline -f execute
end
bind \cx\cg _lnta_ctrl_x_ctrl_g_fix
`

// GenerateInitScript returns the shell integration script for the given shell.
// Supported shells: "zsh", "bash", "fish".
func GenerateInitScript(shell string, version string) (string, error) {
	var tmpl string
	switch shell {
	case "zsh":
		tmpl = zshTemplate
	case "bash":
		tmpl = bashTemplate
	case "fish":
		tmpl = fishTemplate
	default:
		return "", fmt.Errorf("unsupported shell: %s", shell)
	}
	t := template.Must(template.New("init").Parse(tmpl))
	var buf bytes.Buffer
	data := struct{ Version string }{Version: version}
	if err := t.Execute(&buf, data); err != nil {
		return "", err
	}
	return buf.String(), nil
}
